const Imap = require('imap');

const imapUser = item.json.imap_user;
const imapPass = item.json.imap_pass;
const imapHost = item.json.imap_host;
const imapPort = item.json.imap_port;
const folder = item.json.folder;
const uid = item.json.uid;

const imapConfig = {
  user: imapUser,
  password: imapPass,
  host: imapHost,
  port: imapPort,
  tls: true,
};

// Функция для задержки между попытками
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function openInbox(imapInstance, folderName) {
  return new Promise((resolve, reject) => {
    imapInstance.openBox(folderName, false, (err, box) => {
      if (err) {
        console.error('Error opening folder:', err);
        reject(err);
      } else {
        console.log('Opened folder:', box.name);
        resolve();
      }
    });
  });
}

function addSeenFlag(imapInstance, uid) {
  return new Promise((resolve, reject) => {
    console.log(`Marking UID ${uid} as \\Seen...`);
    imapInstance.addFlags(uid, '\\Seen', (err) => {
      if (err) {
        console.error(`Failed to mark UID ${uid} as \\Seen`, err);
        reject(err);
      } else {
        console.log(`Successfully marked UID ${uid} as \\Seen`);
        resolve();
      }
    });
  });
}

async function connectImap(config) {
  return new Promise((resolve, reject) => {
    const imapInstance = new Imap(config);

    imapInstance.once('ready', () => resolve(imapInstance));
    imapInstance.once('error', reject);
    imapInstance.connect();
  });
}

async function markEmailReadWithRetry() {
  const maxAttempts = 3;
  const retryDelay = 5000; // 5 секунд
  let lastError = null;
  let imapInstance = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    console.log(`\n=== Попытка ${attempt}/${maxAttempts} пометить письмо как прочитанное ===`);

    try {
      // 1. Подключаемся к IMAP
      imapInstance = await connectImap(imapConfig);
      console.log('Успешно подключились к IMAP серверу');

      // 2. Открываем папку
      console.log('Открываем папку:', folder);
      await openInbox(imapInstance, folder);

      // 3. Помечаем письмо как прочитанное
      await addSeenFlag(imapInstance, uid);

      // 4. Закрываем соединение
      imapInstance.end();
      console.log(`✅ Успешно пометили письмо UID ${uid} как прочитанное с попытки ${attempt}`);

      // Записываем информацию о попытке
      item.json.attempts = attempt;
      item.json.last_attempt_successful = true;

      return true;

    } catch (err) {
      lastError = err;
      console.error(`❌ Ошибка в попытке ${attempt}:`, err.message);

      // Закрываем соединение при ошибке
      if (imapInstance && imapInstance.state !== 'disconnected') {
        imapInstance.end();
      }

      // Если не последняя попытка, ждем 5 секунд
      if (attempt < maxAttempts) {
        console.log(`⏳ Ждем ${retryDelay/1000} секунд перед следующей попыткой...`);
        await delay(retryDelay);
      }
    }
  }

  // Если все попытки неудачны
  console.error(`❌ Не удалось пометить письмо как прочитанное после ${maxAttempts} попыток`);
  console.error('Последняя ошибка:', lastError?.message || 'неизвестная ошибка');

  item.json.attempts = maxAttempts;
  item.json.last_attempt_successful = false;
  item.json.last_error = lastError?.message || 'неизвестная ошибка';

  return false;
}

// 🔁 Выполнение с повторными попытками
item.json.read = await markEmailReadWithRetry();
item.json.timestamp = new Date().toISOString();

// Добавляем информацию для отладки
item.json.debug_info = {
  action: 'mark_as_read',
  uid: uid,
  folder: folder,
  host: imapHost,
  max_attempts: 3,
  retry_delay_ms: 5000
};

return item.json;

